#include <stdio.h>
#include <stdlib.h>

static void merge(int a[], int tmp[], int lo, int mid, int hi) {
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi)
        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];   /* <= keeps it stable */
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi)  tmp[k++] = a[j++];
    for (k = lo; k < hi; k++) a[k] = tmp[k];
}

static void sort_range(int a[], int tmp[], int lo, int hi) {
    if (hi - lo < 2) return;                 /* 0 or 1 element: done */
    int mid = lo + (hi - lo) / 2;
    sort_range(a, tmp, lo, mid);
    sort_range(a, tmp, mid, hi);
    merge(a, tmp, lo, mid, hi);
}

void merge_sort(int a[], int n) {
    int *tmp = malloc(n * sizeof *tmp);
    if (!tmp) return;                        /* real code would report the error */
    sort_range(a, tmp, 0, n);
    free(tmp);
}

void merge_sort_bu(int a[], int tmp[], int n) {
    for (int w = 1; w < n; w *= 2) {
        for (int lo = 0; lo < n - w; lo += 2 * w) {
            int mid = lo + w;
            int hi = (lo + 2 * w < n) ? lo + 2 * w : n;
            merge(a, tmp, lo, mid, hi);   /* same merge as above */
        }
    }
}

struct node { int v; struct node *next; };

static struct node *merge_lists(struct node *a, struct node *b) {
    struct node dummy = {0, NULL}, *t = &dummy;
    while (a && b) {
        if (a->v <= b->v) { t->next = a; a = a->next; }
        else              { t->next = b; b = b->next; }
        t = t->next;
    }
    t->next = a ? a : b;
    return dummy.next;
}
